import itertools
import json

def solve_puzzle():
    # Input variables
    houses = [1, 2, 3]  # 1 = leftmost, 3 = rightmost
    names = ["Arnold", "Peter", "Eric"]
    heights = ["short", "average", "very short"]

    solutions = []

    for perm_names in itertools.permutations(names):
        # name_at[house] = name
        name_at = {house: perm_names[i] for i, house in enumerate(houses)}
        pos_of_name = {name_at[h]: h for h in houses}

        # Constraint 1: Peter is somewhere to the right of Eric.
        if not (pos_of_name["Peter"] > pos_of_name["Eric"]):
            continue

        for perm_heights in itertools.permutations(heights):
            height_at = {house: perm_heights[i] for i, house in enumerate(houses)}
            pos_of_height = {height_at[h]: h for h in houses}

            # Constraint 2: The person who is short is in the first house.
            if height_at[1] != "short":
                continue

            # Constraint 3: One house between short and very short.
            if abs(pos_of_height["short"] - pos_of_height["very short"]) != 2:
                continue

            # Constraint 4: Arnold and the person who is very short are next to each other.
            if abs(pos_of_name["Arnold"] - pos_of_height["very short"]) != 1:
                continue

            solutions.append((name_at, height_at))

    if not solutions:
        raise ValueError("No solution found for the given constraints.")

    # Assuming unique solution
    name_at, height_at = solutions[0]

    result = {
        "solution": {
            "header": ["House", "Name", "Height"],
            "rows": [
                [str(h), name_at[h], height_at[h]] for h in sorted(houses)
            ]
        }
    }
    return result

if __name__ == "__main__":
    print(json.dumps(solve_puzzle(), ensure_ascii=False))
